/*
    Sayang sayang Sayang, Sayang?
 */
void mainImage( out vec4 O, in vec2 F )
{
    vec2 R = iResolution.xy,
        st = (2.0 * F - R)/R.y;

    const float interval_length = 2.0;
    int current_interval = int(floor(iTime/interval_length)) % 4;
    float t = smoothstep(0.0, 1.0, mod(iTime, interval_length) / interval_length);
    const vec3 l_colour = vec3(0.05, 0.0, 0.0);
    const vec3 h_colour = vec3(1.0, 0.0, 0.0);
    vec3 mix_colour = vec3(0);
    switch (current_interval)
    {
    case 0:
        mix_colour = mix(l_colour, h_colour, t);
        break;
    case 1:
        mix_colour = h_colour;
        break;
    case 2:
        mix_colour = mix(h_colour, l_colour, t);
        break;
    case 3:
        mix_colour = l_colour;
        break;
    }

    st.y *= 1.5;
    st.y -= 0.5;
    st.x = -0.8*log(length(st*0.025)) + 0.5*acos(st.y/length(st));
    st.y *= 0.05;
    float value = fbm(0.075*iTime+fbm(st*0.5)+fbm(st*0.125+noise(st*2.5+iTime*0.0125)) + st);
    vec3 C = smoothstep(0.35, -0.25, value)*vec3(3.1,0.4,0.65);
    C = mix(C, mix_colour, value);
    O = vec4(gamma(C),1.0);
}

#define TAU        6.283185307179586476925286766559

#define gamma(c) pow(c, vec3(1.0/2.2))

vec2 random(vec2 st)
{
    st = vec2( dot(st,vec2(127.1,311.7)),
              dot(st,vec2(269.5,183.3)) );
    return -1.0 + 2.0*fract(sin(st)*43758.5453123);
}


// Gradient noise by Inigo Quilez.
float noise(in vec2 st)
{
	vec2 ip = floor(st);
	vec2 fp = fract(st);

	vec2 ci = fp*fp*(3.0 - 2.0*fp);
	return mix(mix(dot(random(ip), fp),
	               dot(random(ip + vec2(1.0, 0.0)), fp - vec2(1.0, 0.0)), ci.x),
			   mix(dot(random(ip + vec2(0.0, 1.0)), fp - vec2(0.0, 1.0)),
			       dot(random(ip + vec2(1.0, 1.0)), fp - vec2(1.0, 1.0)), ci.x),
			   ci.y);
}

float fbm(in vec2 st)
{
    float value = 0.0;
    float freq = 1.0;
    float amp = 1.0;

    for (int i = 0; i < 8; ++i)
    {
        value += amp * noise(st*freq);
        freq *= 2.0;
        amp *= 0.5;
    }

    return value;
}
